DECLARE
  PROCEDURE drop_table(p_name VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE ' || p_name || ' PURGE';
  EXCEPTION
    WHEN OTHERS THEN
      IF SQLCODE != -942 THEN RAISE; END IF;  -- -942: таблицы ещё нет
  END;
BEGIN
  drop_table('dml_emp');
  drop_table('dml_emp_arch');
  drop_table('dml_prod');
  drop_table('dml_price_list');

  EXECUTE IMMEDIATE 'CREATE TABLE dml_emp AS SELECT * FROM employees';
  EXECUTE IMMEDIATE 'ALTER TABLE dml_emp ADD CONSTRAINT dml_emp_pk PRIMARY KEY (emp_id)';
  EXECUTE IMMEDIATE 'CREATE TABLE dml_prod AS SELECT * FROM products';
  EXECUTE IMMEDIATE 'ALTER TABLE dml_prod ADD CONSTRAINT dml_prod_pk PRIMARY KEY (prod_id)';
  EXECUTE IMMEDIATE 'CREATE TABLE dml_emp_arch (
                       emp_id    NUMBER(6),
                       full_name VARCHAR2(61),
                       salary    NUMBER(9,2))';
  EXECUTE IMMEDIATE 'CREATE TABLE dml_price_list (
                       prod_id   NUMBER(6),
                       prod_name VARCHAR2(60),
                       category  VARCHAR2(30),
                       price     NUMBER(9,2))';
  EXECUTE IMMEDIATE q'[INSERT INTO dml_price_list
    SELECT 5001, 'Laptop Pro 14',    'Electronics', 1390 FROM dual UNION ALL
    SELECT 5005, 'Wireless Mouse',   'Accessories',   39 FROM dual UNION ALL
    SELECT 5012, 'UPS 1500VA',       'Hardware',     410 FROM dual UNION ALL
    SELECT 5013, 'Webcam HD',        'Accessories',   75 FROM dual UNION ALL
    SELECT 5014, 'Noise Headphones', 'Accessories',  180 FROM dual]';
  COMMIT;
END;

