DECLARE
  v_cnt NUMBER;
  v_sum NUMBER;
BEGIN
  UPDATE dml_emp SET salary = salary + 500 WHERE dept_id = 20;
  SAVEPOINT after_raise;
  SELECT COUNT(*), NVL(SUM(salary), 0) INTO v_cnt, v_sum
    FROM dml_emp WHERE dept_id = 20;
  DBMS_OUTPUT.PUT_LINE('После UPDATE: ' || v_cnt || ' сотр., сумма ' || v_sum);

  DELETE FROM dml_emp WHERE dept_id = 20;
  SELECT COUNT(*), NVL(SUM(salary), 0) INTO v_cnt, v_sum
    FROM dml_emp WHERE dept_id = 20;
  DBMS_OUTPUT.PUT_LINE('После DELETE: ' || v_cnt || ' сотр., сумма ' || v_sum);

  ROLLBACK TO after_raise;   -- отменили только DELETE
  SELECT COUNT(*), NVL(SUM(salary), 0) INTO v_cnt, v_sum
    FROM dml_emp WHERE dept_id = 20;
  DBMS_OUTPUT.PUT_LINE('После ROLLBACK TO: ' || v_cnt || ' сотр., сумма ' || v_sum);

  ROLLBACK;                  -- отменили всю транзакцию
  SELECT COUNT(*), NVL(SUM(salary), 0) INTO v_cnt, v_sum
    FROM dml_emp WHERE dept_id = 20;
  DBMS_OUTPUT.PUT_LINE('После ROLLBACK: ' || v_cnt || ' сотр., сумма ' || v_sum);
END;

