DECLARE
  PROCEDURE try(p_label VARCHAR2, p_sql VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE p_sql;
    DBMS_OUTPUT.PUT_LINE(p_label || ': ok');
  EXCEPTION
    WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE(p_label || ': ошибка ' || SQLCODE);
  END;
BEGIN
  try('норма',             q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (999991, 'Check A', 'a@check.uz', 1000)]');
  try('дубль staff_id',    q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (999991, 'Check B', 'b@check.uz', 1000)]');
  try('staff_id NULL',     q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (NULL, 'Check B', 'b@check.uz', 1000)]');
  try('full_name NULL',    q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (999992, NULL, 'c@check.uz', 1000)]');
  try('дубль email',       q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (999993, 'Check D', 'a@check.uz', 1000)]');
  try('email NULL дважды', q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) SELECT 999993 + LEVEL, 'Check N', NULL, 1000 FROM dual CONNECT BY LEVEL <= 2]');
  try('salary = 0',        q'[INSERT INTO ddl_staff (staff_id, full_name, email, salary) VALUES (999997, 'Check F', 'f@check.uz', 0)]');
  ROLLBACK;
END;

