DECLARE
  v_sal   employees.salary%TYPE;
  v_years NUMBER := 0;
BEGIN
  SELECT salary INTO v_sal FROM employees WHERE emp_id = 114;

  LOOP
    v_sal   := ROUND(v_sal * 1.1, 2);
    v_years := v_years + 1;
    DBMS_OUTPUT.PUT_LINE('Год ' || v_years || ': ' || v_sal);
    EXIT WHEN v_sal >= 3000;
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Лет до 3000: ' || v_years);
END;

