  v_name employees.first_name%TYPE;
BEGIN
  FOR d IN (SELECT dept_id, dept_name
              FROM departments
             ORDER BY dept_id) LOOP
    BEGIN  -- вложенный блок: ошибка не прервёт цикл
      SELECT first_name
        INTO v_name
        FROM employees
       WHERE dept_id = d.dept_id
         AND salary > 3000;
      DBMS_OUTPUT.PUT_LINE(d.dept_name || ': ' || v_name);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE(d.dept_name || ': никого');
      WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE(d.dept_name || ': несколько');
    END;
  END LOOP;
END;

