DECLARE
  e_no_stock EXCEPTION;
  v_prod     products.prod_name%TYPE;
BEGIN
  FOR r IN (SELECT oi.line_no, oi.qty, p.prod_name, p.in_stock
              FROM order_items oi
              JOIN products p ON p.prod_id = oi.prod_id
             WHERE oi.order_id = 9016
             ORDER BY oi.line_no) LOOP
    v_prod := r.prod_name;
    IF r.qty > r.in_stock THEN
      RAISE e_no_stock;  -- сразу в секцию EXCEPTION, цикл прерван
    END IF;
    DBMS_OUTPUT.PUT_LINE('Строка ' || r.line_no || ': ' || r.prod_name || ' — ок');
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Заказ можно отгружать');
EXCEPTION
  WHEN e_no_stock THEN
    DBMS_OUTPUT.PUT_LINE('Не хватает на складе: ' || v_prod);
END;

