DECLARE
  v_done BOOLEAN := FALSE;
BEGIN
  FOR r IN (SELECT oi.line_no, oi.qty, p.prod_name, p.in_stock
              FROM order_items oi JOIN products p ON p.prod_id = oi.prod_id
             WHERE oi.order_id = 9016 ORDER BY oi.line_no) LOOP
    IF r.qty > r.in_stock THEN
      DBMS_OUTPUT.PUT_LINE('Не хватает на складе: ' || r.prod_name);
      v_done := TRUE;
      EXIT;
    END IF;
    DBMS_OUTPUT.PUT_LINE('Строка ' || r.line_no || ': ' || r.prod_name || ' — ок');
  END LOOP;
  IF NOT v_done THEN DBMS_OUTPUT.PUT_LINE('Заказ можно отгружать'); END IF;
END;

