CREATE OR REPLACE PROCEDURE raise_salary_sb_prc (
  p_emp_id IN NUMBER,
  p_pct    IN NUMBER DEFAULT 10
) IS
BEGIN
  UPDATE prc_emp_sb
     SET salary = ROUND(salary * (1 + p_pct / 100), 2)
   WHERE emp_id = p_emp_id;

  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20404, 'Нет сотрудника ' || p_emp_id);
  END IF;
  -- COMMIT не делаем: транзакцией управляет тот, кто вызывает
END raise_salary_sb_prc;

