CREATE OR REPLACE FUNCTION bump_salary_fn (
  p_emp_id IN NUMBER,
  p_amount IN NUMBER
) RETURN NUMBER IS
  v_new prc_emp_sb.salary%TYPE;
BEGIN
  UPDATE prc_emp_sb
     SET salary = salary + p_amount
   WHERE emp_id = p_emp_id
  RETURNING salary INTO v_new;  -- новое значение сразу в переменную
  RETURN v_new;
END bump_salary_fn;

