CREATE OR REPLACE PACKAGE BODY emp_api_pkg IS

  -- приватная функция: её нет в спецификации, снаружи не видна.
  -- объявлена выше тех, кто её вызывает
  FUNCTION get_salary (p_emp_id IN NUMBER) RETURN NUMBER IS
    v_salary employees.salary%TYPE;
  BEGIN
    SELECT salary INTO v_salary FROM employees WHERE emp_id = p_emp_id;
    RETURN v_salary;
  END get_salary;

  FUNCTION full_name (p_emp_id IN NUMBER) RETURN VARCHAR2 IS
    v_name VARCHAR2(61);
  BEGIN
    SELECT first_name || ' ' || last_name
      INTO v_name
      FROM employees
     WHERE emp_id = p_emp_id;
    RETURN v_name;
  END full_name;

  FUNCTION bonus (p_emp_id IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN get_salary(p_emp_id) * c_bonus_pct / 100;
  END bonus;

END emp_api_pkg;

