CREATE OR REPLACE PACKAGE BODY order_seq_pkg IS
  g_last   NUMBER;       -- приватные переменные: живут всю сессию
  g_issued NUMBER := 0;

  FUNCTION next_id RETURN NUMBER IS
  BEGIN
    g_last   := g_last + g_step;
    g_issued := g_issued + 1;
    RETURN g_last;
  END next_id;

  FUNCTION issued_count RETURN NUMBER IS
  BEGIN
    RETURN g_issued;
  END issued_count;

BEGIN
  -- секция инициализации: выполняется один раз при первом обращении в сессии
  SELECT MAX(order_id) INTO g_last FROM orders;
END order_seq_pkg;

check.verify:
DECLARE
  v_max NUMBER;
  v_n0  NUMBER;
  v_a   NUMBER;
  v_b   NUMBER;
BEGIN
  SELECT MAX(order_id) INTO v_max FROM orders;
  v_n0 := order_seq_pkg.issued_count;
  order_seq_pkg.g_step := 10;
  v_a := order_seq_pkg.next_id;
  v_b := order_seq_pkg.next_id;
  DBMS_OUTPUT.PUT_LINE('шаг: ' || (v_b - v_a));
  DBMS_OUTPUT.PUT_LINE('выдано за блок: ' || (order_seq_pkg.issued_count - v_n0));
  DBMS_OUTPUT.PUT_LINE('номер больше MAX(order_id): ' ||
                       CASE WHEN v_a > v_max THEN 'да' ELSE 'нет' END);
END;

