DECLARE
  CURSOR c_emp IS SELECT emp_id FROM employees ORDER BY emp_id;
  TYPE t_ids IS TABLE OF employees.emp_id%TYPE;
  v_ids   t_ids;
  v_batch PLS_INTEGER := 0;
  v_total PLS_INTEGER := 0;
BEGIN
  OPEN c_emp;
  LOOP
    FETCH c_emp BULK COLLECT INTO v_ids LIMIT 6;
    EXIT WHEN v_ids.COUNT = 0;
    v_batch := v_batch + 1;
    v_total := v_total + v_ids.COUNT;
    DBMS_OUTPUT.PUT_LINE('Пачка ' || v_batch || ': ' || v_ids.COUNT);
  END LOOP;
  CLOSE c_emp;
  DBMS_OUTPUT.PUT_LINE('Итого: ' || v_total);
END;

