DECLARE
  TYPE t_prods IS TABLE OF products%ROWTYPE;
  v_prods    t_prods;
  e_bulk_err EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_bulk_err, -24381);
BEGIN
  SELECT * BULK COLLECT INTO v_prods FROM products ORDER BY prod_id;

  FORALL i IN 1 .. v_prods.COUNT SAVE EXCEPTIONS
    INSERT INTO bulk_stock_load (prod_id, in_stock)
    VALUES (v_prods(i).prod_id, v_prods(i).in_stock);
  ROLLBACK;
EXCEPTION
  WHEN e_bulk_err THEN
    DBMS_OUTPUT.PUT_LINE('Вставлено: ' || SQL%ROWCOUNT);
    DBMS_OUTPUT.PUT_LINE('Ошибок: ' || SQL%BULK_EXCEPTIONS.COUNT);
    FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
      DBMS_OUTPUT.PUT_LINE(
        'Строка ' || SQL%BULK_EXCEPTIONS(j).ERROR_INDEX ||
        ' (prod_id ' || v_prods(SQL%BULK_EXCEPTIONS(j).ERROR_INDEX).prod_id ||
        '): ORA-' || LPAD(SQL%BULK_EXCEPTIONS(j).ERROR_CODE, 5, '0'));
    END LOOP;
    ROLLBACK;
END;

