CREATE OR REPLACE TRIGGER mut_emp_max_trg
FOR UPDATE OF salary ON mut_emp
COMPOUND TRIGGER
  TYPE t_ids IS TABLE OF mut_emp.emp_id%TYPE;
  g_ids t_ids := t_ids();

  BEFORE EACH ROW IS
  BEGIN
    g_ids.EXTEND;
    g_ids(g_ids.LAST) := :NEW.emp_id;   -- только запоминаем
  END BEFORE EACH ROW;

  AFTER STATEMENT IS
    v_cnt PLS_INTEGER;
  BEGIN
    FOR i IN 1 .. g_ids.COUNT LOOP
      SELECT COUNT(*) INTO v_cnt
        FROM mut_emp e
        JOIN mut_emp m ON m.emp_id = e.manager_id
       WHERE e.emp_id = g_ids(i)
         AND e.salary > m.salary;
      IF v_cnt > 0 THEN
        RAISE_APPLICATION_ERROR(-20001,
          'Сотрудник ' || g_ids(i) || ' получает больше менеджера');
      END IF;
    END LOOP;
  END AFTER STATEMENT;
END mut_emp_max_trg;

