    DBMS_OUTPUT.PUT_LINE('Ошибка: ' || SQLERRM);
    DBMS_OUTPUT.PUT_LINE('Где: ' || SUBSTR(v_bt, 1, INSTR(v_bt, CHR(10)) - 1));
END;

