lessons.setup:
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE plan_orders PURGE';
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  -- 50 000 заказов: по 50 в день начиная с 2023-01-01, cust_code — строка из цифр
  EXECUTE IMMEDIATE q'[
    CREATE TABLE plan_orders AS
    SELECT LEVEL                                        AS order_id,
           TO_CHAR(MOD(LEVEL, 1000))                    AS cust_code,
           DATE '2023-01-01' + TRUNC((LEVEL - 1) / 50)  AS order_date,
           MOD(LEVEL * 13, 5000) + 10                   AS amount,
           DECODE(MOD(LEVEL, 4), 0, 'NEW', 1, 'PAID', 2, 'SHIPPED', 'CANCELLED') AS status
      FROM dual
   CONNECT BY LEVEL <= 50000]';
  EXECUTE IMMEDIATE 'ALTER TABLE plan_orders ADD CONSTRAINT plan_orders_pk PRIMARY KEY (order_id)';
  EXECUTE IMMEDIATE 'CREATE INDEX plan_orders_cust_ix ON plan_orders (cust_code)';
  EXECUTE IMMEDIATE 'CREATE INDEX plan_orders_date_ix ON plan_orders (order_date)';
  -- ещё 10 000 строк обычным INSERT: статистика о них не знает
  EXECUTE IMMEDIATE q'[
    INSERT INTO plan_orders
    SELECT 50000 + LEVEL, TO_CHAR(MOD(LEVEL, 1000)), DATE '2025-09-27' + TRUNC((LEVEL - 1) / 50),
           MOD(LEVEL * 13, 5000) + 10, 'NEW'
      FROM dual
   CONNECT BY LEVEL <= 10000]';
  COMMIT;
END;

